SELECT NVL(MAX(tr_seq), 0) + 1
  FROM SYT1MG
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = #{trYmd}
   AND FUND_CD = #{fundCd}
   AND JM_CD   = #{jmCd}
   AND TR_CD   = #{trCd}

